def process(tle48445Parse) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    from skyfield.api import EarthSatellite, load, utc

    df = tle48445Parse.copy()

    ts = load.timescale()

    # Mean Earth radius (meters) for a simple geocentric altitude estimate
    earthRadiusM = 6_371_000.0

    def altitudeM(l1: str, l2: str, epoch: pd.Timestamp) -> float:
        sat = EarthSatellite(l1, l2, '48445', ts)

        # Skyfield requires timezone-aware UTC datetimes
        dt = epoch.to_pydatetime()
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=utc)
        else:
            dt = dt.astimezone(utc)

        t = ts.from_datetime(dt)

        geocentric = sat.at(t)

        # Try Earth-fixed ITRF position first
        try:
            from skyfield.framelib import itrf
            pos_m = geocentric.frame_xyz(itrf).m
        except Exception:
            pos_m = geocentric.position.m

        return float(np.linalg.norm(pos_m) - earthRadiusM)

    df['altitudeM'] = [
        altitudeM(l1, l2, ep)
        for l1, l2, ep in zip(df['line1'].tolist(), df['line2'].tolist(), df['epoch'].tolist())
    ]

    return df[['epoch', 'altitudeM', 'line1', 'line2']]
